#!/usr/bin/env node
// Run this once (and again any time you change the pdfjs-dist version):
//   npm install pdfjs-dist@2.16.105
//   node scripts/generate-pdfjs-source.js
//
// Reads the installed pdf.js build and writes it out as a plain TS string
// constant (src/lib/pdfjsSource.generated.ts) that Metro bundles like any
// other source file — no metro.config.js changes, no custom asset
// extensions, no network fetch at runtime. The generated file is checked
// into git like any other source file (it only needs regenerating if you
// change the pdfjs-dist version).
const fs = require("fs");
const path = require("path");

const candidates = [
  "node_modules/pdfjs-dist/build/pdf.min.js",
  "node_modules/pdfjs-dist/build/pdf.js",
  "node_modules/pdfjs-dist/legacy/build/pdf.min.js",
  "node_modules/pdfjs-dist/legacy/build/pdf.js",
];

let srcPath = null;
for (const c of candidates) {
  const full = path.join(__dirname, "..", c);
  if (fs.existsSync(full)) {
    srcPath = full;
    break;
  }
}

if (!srcPath) {
  console.error("Could not find a pdfjs-dist build file. Did you run:");
  console.error("  npm install pdfjs-dist@2.16.105");
  console.error("first? (run from the frontend/ directory)");
  process.exit(1);
}

const source = fs.readFileSync(srcPath, "utf8");
const outPath = path.join(__dirname, "..", "src", "lib", "pdfjsSource.generated.ts");

const banner =
  "// AUTO-GENERATED by scripts/generate-pdfjs-source.js — do not hand-edit.\n" +
  "// Regenerate with: node scripts/generate-pdfjs-source.js\n" +
  `// Source: ${path.relative(path.join(__dirname, ".."), srcPath)}\n\n`;

const content = banner + "export const PDFJS_LIB_SOURCE = " + JSON.stringify(source) + ";\n";

fs.writeFileSync(outPath, content, "utf8");
console.log(`Wrote ${content.length.toLocaleString()} chars to src/lib/pdfjsSource.generated.ts`);
console.log(`(pdf.js source was ${source.length.toLocaleString()} chars, read from ${path.relative(path.join(__dirname, ".."), srcPath)})`);
